    def fmt(a, b):
        return f"{len(a)} {len(b)}\n" + " ".join(map(str, a)) + "\n" + " ".join(map(str, b))
    def srt(n, lo, hi):
        return sorted(rng.randint(lo, hi) for _ in range(n))
    tests = [fmt([1], [2]), fmt([2], [1]), fmt([1], [1]), fmt([3, 3], [3, 3]), fmt([5, 6], [1, 2]), fmt([1, 2], [5, 6]),
             fmt([-10 ** 9, 0, 10 ** 9], [-10 ** 9, 10 ** 9]), fmt([1, 5, 9], [2, 3, 10, 11]), fmt([-2, -2, 6], [-2, 4])]
    for _ in range(30):
        tests.append(fmt(srt(rng.randint(1, 8), -5, 5), srt(rng.randint(1, 8), -5, 5)))
    for _ in range(10):
        tests.append(fmt(srt(rng.randint(5, 20), -100, 100), srt(rng.randint(5, 20), -100, 100)))
